    #[inline(always)]
    fn lex_quoted(&self, open: usize) -> Lexed<'a> {
        let b = self.src.as_bytes();
        let start = open + 1;
        let mut i = start;
        loop {
            match b.get(i) {
                None => return Err(LexError::UnterminatedQuote { pos: open }),
                Some(b'"') => break,
                Some(b'\\') => match b.get(i + 1) {
                    None => return Err(LexError::UnterminatedQuote { pos: open }),
                    Some(b'"' | b'\\' | b'n' | b't') => i += 2,
                    Some(_) => return Err(LexError::InvalidEscape { pos: i }),
                },
                Some(_) => i += 1,
            }
        }
        expect_separator(b, i)?;
        Ok((Token::Quoted(&self.src[start..i]), i + 1))
    }

    /// An unquoted value up to the next separator; may be empty.
    #[inline(always)]
    fn lex_bare(&self, start: usize) -> Lexed<'a> {
        let b = self.src.as_bytes();
        let mut i = start;
        while i < b.len() && !is_separator(b[i]) {
            if b[i] == b'"' {
                return Err(LexError::UnexpectedQuote { pos: i });
            }
            i += 1;
        }
        Ok((Token::Bare(&self.src[start..i]), i))
    }

