use crate::error::LexError;

/// One piece of a log line, borrowed from the line itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Token<'a> {
    /// The text between `[` and `]`.
    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// What the tokenizer expects at its current position.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// Between tokens: a timestamp, a key or a word may follow.
    Start,
    /// Right after `key=`: the value follows.
    Value,
    /// An error was reported; nothing more is yielded.
    Done,
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Start }
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

/// A successfully lexed token and the byte offset just past it.
type Lexed<'a> = Result<(Token<'a>, usize), LexError>;

#[inline(always)]
fn is_separator(byte: u8) -> bool {
    byte == b' ' || byte == b'\t'
}

/// Checks that the byte after a closing `]` or `"` at `close` is a separator or the end of the line.
#[inline(always)]
fn expect_separator(b: &[u8], close: usize) -> Result<(), LexError> {
    let after = close + 1;
    if after < b.len() && !is_separator(b[after]) {
        return Err(LexError::ExpectedSeparator { pos: after });
    }
    Ok(())
}

impl<'a> Tokens<'a> {
    /// `[...]` starting at `open`. The timestamp may not contain `[`.
    #[inline(always)]
    fn lex_timestamp(&self, open: usize) -> Lexed<'a> {
        let b = self.src.as_bytes();
        let start = open + 1;
        let mut i = start;
        loop {
            match b.get(i) {
                None => return Err(LexError::UnterminatedTimestamp { pos: open }),
                Some(b']') => break,
                Some(b'[') => return Err(LexError::NestedBracket { pos: i }),
                Some(_) => i += 1,
            }
        }
        expect_separator(b, i)?;
        Ok((Token::Timestamp(&self.src[start..i]), i + 1))
    }

    /// A run up to the next separator or `=`; a key if `=` ends it, otherwise a word.
    /// The flag says whether a value follows.
    #[inline(always)]
    fn lex_key_or_word(&self, start: usize) -> Result<(Token<'a>, usize, bool), LexError> {
        let b = self.src.as_bytes();
        let mut i = start;
        while i < b.len() && !is_separator(b[i]) && b[i] != b'=' {
            if b[i] == b'"' {
                return Err(LexError::UnexpectedQuote { pos: i });
            }
            i += 1;
        }
        let text = &self.src[start..i];
        if i < b.len() && b[i] == b'=' {
            Ok((Token::Key(text), i + 1, true))
        } else {
            Ok((Token::Word(text), i, false))
        }
    }

    /// `"..."` starting at `open`, with the escapes `\"`, `\\`, `\n` and `\t`.
    #[inline(always)]
    fn lex_quoted(&self, open: usize) -> Lexed<'a> {
        let b = self.src.as_bytes();
        let start = open + 1;
        let mut i = start;
        loop {
            match b.get(i) {
                None => return Err(LexError::UnterminatedQuote { pos: open }),
                Some(b'"') => break,
                Some(b'\\') => match b.get(i + 1) {
                    None => return Err(LexError::UnterminatedQuote { pos: open }),
                    Some(b'"' | b'\\' | b'n' | b't') => i += 2,
                    Some(_) => return Err(LexError::InvalidEscape { pos: i }),
                },
                Some(_) => i += 1,
            }
        }
        expect_separator(b, i)?;
        Ok((Token::Quoted(&self.src[start..i]), i + 1))
    }

    /// An unquoted value up to the next separator; may be empty.
    #[inline(always)]
    fn lex_bare(&self, start: usize) -> Lexed<'a> {
        let b = self.src.as_bytes();
        let mut i = start;
        while i < b.len() && !is_separator(b[i]) {
            if b[i] == b'"' {
                return Err(LexError::UnexpectedQuote { pos: i });
            }
            i += 1;
        }
        Ok((Token::Bare(&self.src[start..i]), i))
    }

    /// The next token when between tokens, or `None` at the end of the line.
    #[inline(always)]
    fn next_in_start(&mut self) -> Option<Result<Token<'a>, LexError>> {
        let b = self.src.as_bytes();
        let mut p = self.pos;
        while p < b.len() && is_separator(b[p]) {
            p += 1;
        }
        self.pos = p;
        let first = *b.get(p)?;
        let lexed = match first {
            b'[' => self.lex_timestamp(p),
            b'"' => Err(LexError::UnexpectedQuote { pos: p }),
            b'=' => Err(LexError::EmptyKey { pos: p }),
            _ => self.lex_key_or_word(p).map(|(token, end, value_follows)| {
                if value_follows {
                    self.state = State::Value;
                }
                (token, end)
            }),
        };
        Some(self.finish(lexed))
    }

    /// The value right after `key=`.
    #[inline(always)]
    fn next_in_value(&mut self) -> Result<Token<'a>, LexError> {
        let p = self.pos;
        self.state = State::Start;
        let lexed = match self.src.as_bytes().get(p) {
            Some(b'"') => self.lex_quoted(p),
            _ => self.lex_bare(p),
        };
        self.finish(lexed)
    }

    /// Advances past a lexed token, or stops the stream on an error.
    #[inline(always)]
    fn finish(&mut self, lexed: Lexed<'a>) -> Result<Token<'a>, LexError> {
        match lexed {
            Ok((token, end)) => {
                self.pos = end;
                Ok(token)
            }
            Err(error) => {
                self.state = State::Done;
                self.pos = self.src.len();
                Err(error)
            }
        }
    }
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        match self.state {
            State::Start => self.next_in_start(),
            State::Value => Some(self.next_in_value()),
            State::Done => None,
        }
    }
}

