        let lexed = match first {
            b'[' => self.lex_timestamp(p),
            b'"' => Err(LexError::UnexpectedQuote { pos: p }),
            b'=' => Err(LexError::EmptyKey { pos: p }),
            _ => self.lex_key_or_word(p).map(|(token, end, value_follows)| {
                if value_follows {
                    self.state = State::Value;
                }
                (token, end)
            }),
        };
        Some(self.finish(lexed))
    }

    /// The value right after `key=`.
    #[inline(always)]
    fn next_in_value(&mut self) -> Result<Token<'a>, LexError> {
        let p = self.pos;
        self.state = State::Start;
        let lexed = match self.src.as_bytes().get(p) {
            Some(b'"') => self.lex_quoted(p),
            _ => self.lex_bare(p),
        };
        self.finish(lexed)
    }

    /// Advances past a lexed token, or stops the stream on an error.
    #[inline(always)]
    fn finish(&mut self, lexed: Lexed<'a>) -> Result<Token<'a>, LexError> {
        match lexed {
            Ok((token, end)) => {
                self.pos = end;
                Ok(token)
            }
            Err(error) => {
                self.state = State::Done;
                self.pos = self.src.len();
                Err(error)
            }
        }
    }
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        match self.state {
            State::Start => self.next_in_start(),
            State::Value => Some(self.next_in_value()),
            State::Done => None,
        }
    }
}

